import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 신청 직후 결재 상태는 '기안' (BEHAVIOR.md 값의 출처)
const INITIAL_STATUS = '기안';
// 가정: 조회 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr01807Controller {
  @Post('/attendance-requests/trips')
  @HttpCode(200)
  async createTripRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const data = checks.inputOf(req.body);
    const invalid = () =>
      new ApiError(422, 'INVALID_TRIP_PERIOD', '필수 값이 누락되었거나 기간이 올바르지 않습니다.');
    const typeId = data['attendanceTypeId'];
    const category = data['tripCategory'];
    const startDate = data['startDate'];
    const endDate = data['endDate'];
    const place = data['tripPlace'];
    const reason = data['reason'];
    const travelers = data['travelers'];
    if (typeId === undefined || typeId === null || typeId === '' || isNaN(Number(typeId))) {
      throw invalid();
    }
    if (category !== '출장' && category !== '외근') {
      throw invalid();
    }
    if (typeof startDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(startDate)) {
      throw invalid();
    }
    if (typeof endDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(endDate)) {
      throw invalid();
    }
    if (endDate < startDate) {
      throw invalid();
    }
    if (typeof place !== 'string' || place.trim() === '' || place.length > 200) {
      throw invalid();
    }
    if (reason !== undefined && reason !== null && (typeof reason !== 'string' || reason.length > 1000)) {
      throw invalid();
    }
    if (!Array.isArray(travelers) || travelers.length === 0) {
      throw invalid();
    }
    const seen = new Set<string>();
    for (const t of travelers) {
      if (!t || typeof t !== 'object') {
        throw invalid();
      }
      const eid = (t as Record<string, unknown>)['employeeId'];
      const tr = (t as Record<string, unknown>)['transport'];
      if (eid === undefined || eid === null || eid === '' || isNaN(Number(eid))) {
        throw invalid();
      }
      if (tr !== undefined && tr !== null && (typeof tr !== 'string' || tr.length > 100)) {
        throw invalid();
      }
      if (seen.has(String(Number(eid)))) {
        throw invalid();
      }
      seen.add(String(Number(eid)));
    }
    return transaction(async (db) => {
      const types = await db.query(
        'SELECT attendance_type_id FROM attendance_type WHERE attendance_type_id = CAST(:typeId AS bigint)',
        { typeId: Number(typeId) },
      );
      if (types.length === 0) {
        throw invalid();
      }
      for (const t of travelers as Record<string, unknown>[]) {
        const emp = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId: Number(t['employeeId']) },
        );
        if (emp.length === 0) {
          throw invalid();
        }
      }
      const rows = await db.query(
        `INSERT INTO attendance_request
           (employee_id, attendance_type_id, start_date, end_date, reason, trip_category, trip_place, approval_status, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), CAST(:typeId AS bigint), CAST(:startDate AS date), CAST(:endDate AS date), :reason, :category, :place, :status, now(), now())
         RETURNING attendance_request_id AS "attendanceRequestId", approval_status AS "approvalStatus"`,
        {
          userId: user.id,
          typeId: Number(typeId),
          startDate,
          endDate,
          reason: reason ?? null,
          category,
          place,
          status: INITIAL_STATUS,
        },
      );
      const created = rows[0];
      for (const t of travelers as Record<string, unknown>[]) {
        await db.execute(
          `INSERT INTO trip_traveler (attendance_request_id, employee_id, transport, created_at, updated_at)
           VALUES (CAST(:requestId AS bigint), CAST(:employeeId AS bigint), :transport, now(), now())`,
          {
            requestId: created['attendanceRequestId'],
            employeeId: Number(t['employeeId']),
            transport: t['transport'] ?? null,
          },
        );
      }
      return created;
    });
  }

  @Get('/attendance-requests/trips')
  async listTripRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const q = checks.queryOf(req.query);
    const invalid = () =>
      new ApiError(422, 'INVALID_SEARCH_PERIOD', '조회 기간이 올바르지 않습니다.');
    const dateOf = (v: unknown): string | null => {
      if (v === undefined || v === null || v === '') {
        return null;
      }
      if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) {
        throw invalid();
      }
      return v;
    };
    const numOf = (v: unknown): number | null => {
      if (v === undefined || v === null || v === '') {
        return null;
      }
      const n = Number(v);
      if (isNaN(n)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '숫자 형식이 올바르지 않습니다.');
      }
      return n;
    };
    const startDate = dateOf(q['startDate']);
    const endDate = dateOf(q['endDate']);
    if (startDate !== null && endDate !== null && endDate < startDate) {
      throw invalid();
    }
    const departmentId = numOf(q['departmentId']);
    const employeeId = numOf(q['employeeId']);
    const pageNo = Math.max(0, numOf(q['page']) ?? 0);
    const size = Math.min(MAX_SIZE, Math.max(1, numOf(q['size']) ?? DEFAULT_SIZE));
    const isAll = user.has ? false : false;
    void isAll;
    return transaction(async (db) => {
      // 권한 범위: 임직원은 본인 신청 또는 본인이 출장자인 건만 조회한다 (가정)
      const where = `
        (CAST(:startDate AS date) IS NULL OR r.end_date >= CAST(:startDate AS date))
        AND (CAST(:endDate AS date) IS NULL OR r.start_date <= CAST(:endDate AS date))
        AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))
        AND (CAST(:employeeId AS bigint) IS NULL OR t.employee_id = CAST(:employeeId AS bigint))
        AND r.trip_category IS NOT NULL
        AND (CAST(:scopeAll AS boolean) OR r.employee_id = CAST(:userId AS bigint) OR t.employee_id = CAST(:userId AS bigint))`;
      const params = {
        startDate,
        endDate,
        departmentId,
        employeeId,
        userId: user.id,
        scopeAll: user.hasRole ? user.hasRole('근태 담당자') : false,
      };
      const from = `
        FROM attendance_request r
        JOIN trip_traveler t ON t.attendance_request_id = r.attendance_request_id
        JOIN employee e ON e.employee_id = t.employee_id`;
      const totalRows = await db.query(`SELECT COUNT(*) AS "total" ${from} WHERE ${where}`, params);
      const items = await db.query(
        `SELECT r.attendance_request_id AS "attendanceRequestId",
                r.trip_category AS "tripCategory",
                r.start_date AS "startDate",
                r.end_date AS "endDate",
                r.trip_place AS "tripPlace",
                r.approval_status AS "approvalStatus",
                t.employee_id AS "travelerEmployeeId",
                t.transport AS "transport"
         ${from}
         WHERE ${where}
         ORDER BY r.attendance_request_id DESC, t.trip_traveler_id
         LIMIT CAST(:limit AS bigint) OFFSET CAST(:offset AS bigint)`,
        { ...params, limit: size, offset: pageNo * size },
      );
      return { items, page: pageNo, size, total: Number(totalRows[0]['total']) };
    });
  }
}

