import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

interface Traveler {
  employeeId: number | string;
  transport: string;
}

export default function FnSfr01807Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);

  const [typeId, setTypeId] = useState<number | string>('');
  const [category, setCategory] = useState('');
  const [fStart, setFStart] = useState('');
  const [fEnd, setFEnd] = useState('');
  const [place, setPlace] = useState('');
  const [reason, setReason] = useState('');
  const [travelers, setTravelers] = useState<Traveler[]>([{ employeeId: '', transport: '' }]);

  const list = useData<Page>(
    () => call<Page>('GET', '/attendance-requests/trips', role, undefined, { ...applied, page, size: 20 }),
    [role, applied, page],
  );

  const search = () => {
    setPage(0);
    setApplied({ startDate, endDate, departmentId, employeeId });
  };
  const reset = () => {
    setStartDate('');
    setEndDate('');
    setDepartmentId('');
    setEmployeeId('');
    setPage(0);
    setApplied({});
  };

  const openForm = () => {
    setTypeId('');
    setCategory('');
    setFStart('');
    setFEnd('');
    setPlace('');
    setReason('');
    setTravelers([{ employeeId: '', transport: '' }]);
    setOpen(true);
  };

  const updateTraveler = (i: number, patch: Partial<Traveler>) => {
    setTravelers(travelers.map((t, idx) => (idx === i ? { ...t, ...patch } : t)));
  };

  const submit = async () => {
    if (typeId === '' || !category || !fStart || !fEnd || !place.trim()) {
      throw new Error('필수 값을 모두 입력하세요.');
    }
    if (fEnd < fStart) {
      throw new Error('종료일은 시작일 이후여야 합니다.');
    }
    if (travelers.length === 0 || travelers.some((t) => t.employeeId === '')) {
      throw new Error('출장자를 선택하세요.');
    }
    await call('POST', '/attendance-requests/trips', role, {
      attendanceTypeId: typeId,
      tripCategory: category,
      startDate: fStart,
      endDate: fEnd,
      tripPlace: place,
      reason,
      travelers: travelers.map((t) => ({ employeeId: t.employeeId, transport: t.transport })),
    });
    notify('출장·외근 신청을 등록했습니다.');
    setOpen(false);
    list.reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>출장 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
          <Field label="사원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openForm}>출장·외근 신청</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={list.data?.items ?? []}
          onRowClick={(row) => setDetail(row)}
          empty="조회된 출장 내역이 없습니다."
          columns={[
            { key: 'tripCategory', label: '출장·외근 구분' },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'tripPlace', label: '장소' },
            { key: 'travelerEmployeeId', label: '출장자', render: (r) => <RefName table="employee" role={role} value={r.travelerEmployeeId} /> },
            { key: 'transport', label: '이동수단' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
        />
        <Pager page={list.data?.page ?? 0} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      {detail ? (
        <Drawer title="출장 상세" onClose={() => setDetail(null)}>
          <dl>
            <dt>출장·외근 구분</dt>
            <dd>{String(detail.tripCategory ?? '')}</dd>
            <dt>기간</dt>
            <dd>
              <DateText value={detail.startDate} /> ~ <DateText value={detail.endDate} />
            </dd>
            <dt>장소</dt>
            <dd>{String(detail.tripPlace ?? '')}</dd>
            <dt>출장자</dt>
            <dd><RefName table="employee" role={role} value={detail.travelerEmployeeId} /></dd>
            <dt>이동수단</dt>
            <dd>{String(detail.transport ?? '')}</dd>
            <dt>결재 진행 상태</dt>
            <dd><Badge value={detail.approvalStatus} /></dd>
          </dl>
        </Drawer>
      ) : null}

      {open ? (
        <Drawer title="출장·외근 신청" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="신청">
            <Field label="근태항목" required>
              <LookupSelect table="attendance_type" role={role} value={typeId} onChange={setTypeId} />
            </Field>
            <Field label="출장·외근 구분" required>
              <Select value={category} onChange={setCategory} options={[['출장', '출장'], ['외근', '외근']]} />
            </Field>
            <Field label="시작일" required>
              <DateInput value={fStart} onChange={setFStart} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={fEnd} onChange={setFEnd} />
            </Field>
            <Field label="장소" required wide>
              <TextInput value={place} onChange={setPlace} />
            </Field>
            <Field label="사유" wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            {travelers.map((t, i) => (
              <div key={i}>
                <Field label={'출장자 ' + (i + 1)} required>
                  <LookupSelect table="employee" role={role} value={t.employeeId} onChange={(v) => updateTraveler(i, { employeeId: v })} />
                </Field>
                <Field label="이동수단">
                  <TextInput value={t.transport} onChange={(v) => updateTraveler(i, { transport: v })} />
                </Field>
                {travelers.length > 1 ? (
                  <button type="button" onClick={() => setTravelers(travelers.filter((_, idx) => idx !== i))}>
                    출장자 삭제
                  </button>
                ) : null}
              </div>
            ))}
            <button type="button" onClick={() => setTravelers([...travelers, { employeeId: '', transport: '' }])}>
              출장자 추가
            </button>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
